mapper.select:
SELECT a.ID as orgId,a.NAME as orgName, #{year} as year,#{month} as month, b.ID as id,b.NOTE as note,b.ATTACHMENTS as attachments, b.SN as sn,b.MODEL_ID as modelId,b.PROCESS_INSTANCE_ID as processInstanceId,b.STATUS as status, IF(b.ID is null,'否','是') as isApply FROM SYS_ORG a left join HR_SUB_SALARY b on a.ID = b.ORG_ID and b.DELETE_FLAG='NOT_DELETE' and b.STATUS in ('0','1')
and b.YEAR=#{year}
and b.MONTH=#{month}
${ew.customSqlSegment}
